                                }
                                goto exit;
                        }
                        cil_list_append(*perm_datums, CIL_DATUM, perm_datum);
                } else {
                        cil_list_append(*perm_datums, curr->flavor, curr->data);
                }
        }

        return SEPOL_OK;

exit:
        cil_list_destroy(perm_datums, CIL_FALSE);
        return rc;
}

